export function validPoint(p){return !!p&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180;}
export function distance(a,b){if(!validPoint(a)||!validPoint(b))throw new Error('유효한 위도·경도가 필요합니다.');const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lon-a.lon)*r,x=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(Math.max(0,x)),Math.sqrt(Math.max(0,1-x)));}
export function interpolate(a,b,t){if(!validPoint(a)||!validPoint(b))throw Error('Invalid point');t=Math.max(0,Math.min(1,Number(t)));if(!Number.isFinite(t))throw Error('Invalid progress');if(t===0)return {...a};if(t===1)return {...b};const r=Math.PI/180,v=p=>[Math.cos(p.lat*r)*Math.cos(p.lon*r),Math.cos(p.lat*r)*Math.sin(p.lon*r),Math.sin(p.lat*r)],u=v(a),w=v(b),omega=Math.acos(Math.max(-1,Math.min(1,u.reduce((n,x,i)=>n+x*w[i],0))));if(omega<1e-12)return {...a};const x=u.map((n,i)=>(Math.sin((1-t)*omega)*n+Math.sin(t*omega)*w[i])/Math.sin(omega));return {lat:Math.atan2(x[2],Math.hypot(x[0],x[1]))/r,lon:Math.atan2(x[1],x[0])/r};}
export function measure(tee,current,green){const total=distance(tee,green),remaining=distance(current,green),fromTee=distance(tee,current);return {total,remaining,fromTee,progress:total>0?Math.max(0,Math.min(1,1-remaining/total)):0};}
export function validatePack(pack){if(pack?.schemaVersion!==1||!pack.id||!Array.isArray(pack.courses)||!validPoint(pack.location))throw Error('Invalid course pack');let count=0;for(const c of pack.courses){if(!c.id||!c.name||!Array.isArray(c.holes)||c.holes.length!==9)throw Error('Each course needs 9 holes');const seen=new Set();for(const h of c.holes){if(!Number.isInteger(h.number)||h.number<1||h.number>9||seen.has(h.number))throw Error('Duplicate/invalid hole');seen.add(h.number);if(![3,4,5,6].includes(h.par)||!Array.isArray(h.greens)||!h.greens.length)throw Error('Invalid hole');for(const g of h.greens){if(!g.id||!validPoint(g)||!g.source?.url||!g.verification)throw Error('Invalid green');count++;}for(const t of h.tees||[]){if(!validPoint(t)||!t.source?.url)throw Error('Invalid tee');count++;}}}return count;}
export function greenFor(pack,course,hole,greenId='A'){return pack.courses.find(c=>c.id===course)?.holes.find(h=>h.number===hole)?.greens.find(g=>g.id===greenId)||null;}
